from datetime import datetime

def en_retard(dernieres, maintenant, limite):
    fin = datetime.strptime(maintenant, "%Y-%m-%d %H:%M")
    resultat = []
    for machine, texte in dernieres.items():
        debut = datetime.strptime(texte, "%Y-%m-%d %H:%M")
        if (fin - debut).total_seconds() / 3600 > limite:
            resultat.append(machine)
    return sorted(resultat)

def evaluer_plan(plan):
    copies = plan["copies"]
    conseils = []
    if len(copies) < 3:
        conseils.append("ajouter des copies")
    if len({c["support"] for c in copies}) < 2:
        conseils.append("varier les supports")
    if not any(c["lieu"] != "bureau" for c in copies):
        conseils.append("garder une copie hors site")
    if plan["frequence_h"] > 24:
        conseils.append("sauvegarder au moins toutes les 24 h")
    if plan["dernier_test_jours"] > 90:
        conseils.append("tester une restauration")
    return conseils or ["plan conforme"]
